import React, { useEffect, useState } from 'react';
import Sidebar from './Sidebar';
import Topbar from './Topbar';

const AppShell = ({ children, currentUser, canApprove, onOpenChat, onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('okoa_theme') === 'dark');

  useEffect(() => {
    document.documentElement.classList.toggle('dark', darkMode);
    localStorage.setItem('okoa_theme', darkMode ? 'dark' : 'light');
  }, [darkMode]);

  return (
    <div className={`app-shell ${darkMode ? 'dark-shell' : ''}`}>
      <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} canApprove={canApprove} onOpenChat={onOpenChat} />
      <div className="app-shell-content">
        <Topbar currentUser={currentUser} onMenu={() => setSidebarOpen(true)} onLogout={onLogout} darkMode={darkMode} onToggleTheme={() => setDarkMode((value) => !value)} />
        {children}
      </div>
    </div>
  );
};

export default AppShell;
